void bubbleSort(int arr[], int n) {
    for (int i = 0; i < n-1; i++) {
        for (int j = 0; j < n-i-1; j++) {
            if (arr[j] > arr[j+1]) {
                int temp = arr[j];
                arr[j] = arr[j+1];
                arr[j+1] = temp;
            }
        }
    }
}

#include <iostream>
#include <vector>
#include <queue>
#include <limits>
#include <algorithm>
#include <functional>
using namespace std;

class Graph {
private:
    int V;
    vector<vector<pair<int, int>>> adj;

public:
    Graph(int vertices) : V(vertices), adj(vertices) {}

    void addEdge(int u, int v, int weight) {
        if (u < 0 || v < 0 || u >= V || v >= V || weight < 0)
            return;

        adj[u].push_back({v, weight});
    }

    vector<int> shortestPath(int source) {
        vector<int> distance(V, numeric_limits<int>::max());
        vector<int> parent(V, -1);

        priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> pq;

        distance[source] = 0;
        pq.push({0, source});

        while (!pq.empty()) {
            auto [currentDistance, u] = pq.top();
            pq.pop();

            if (currentDistance > distance[u])
                continue;

            for (const auto& edge : adj[u]) {
                int v = edge.first;
                int weight = edge.second;

                if (distance[u] != numeric_limits<int>::max() &&
                    distance[u] + weight < distance[v]) {
                    distance[v] = distance[u] + weight;
                    parent[v] = u;
                    pq.push({distance[v], v});
                }
            }
        }

        return distance;
    }

    void printAllPaths(int source, int destination) {
        vector<bool> visited(V, false);
        vector<int> path;

        function<void(int)> dfs = [&](int current) {
            visited[current] = true;
            path.push_back(current);

            if (current == destination) {
                for (size_t i = 0; i < path.size(); ++i) {
                    cout << path[i];
                    if (i + 1 < path.size())
                        cout << " -> ";
                }
                cout << endl;
            } else {
                for (const auto& edge : adj[current]) {
                    int next = edge.first;

                    if (!visited[next])
                        dfs(next);
                }
            }

            path.pop_back();
            visited[current] = false;
        };

        dfs(source);
    }
};

int longestIncreasingSubsequence(const vector<int>& nums) {
    if (nums.empty())
        return 0;

    vector<int> dp(nums.size(), 1);

    for (size_t i = 1; i < nums.size(); ++i) {
        for (size_t j = 0; j < i; ++j) {
            if (nums[j] < nums[i]) {
                dp[i] = max(dp[i], dp[j] + 1);
            }
        }
    }

    return *max_element(dp.begin(), dp.end());
}

int main() {
    Graph graph(6);

    graph.addEdge(0, 1, 4);
    graph.addEdge(0, 2, 2);
    graph.addEdge(1, 2, 5);
    graph.addEdge(1, 3, 10);
    graph.addEdge(2, 4, 3);
    graph.addEdge(4, 3, 4);
    graph.addEdge(3, 5, 11);

    vector<int> distances = graph.shortestPath(0);

    for (int i = 0; i < distances.size(); ++i) {
        cout << "Distance to " << i << ": ";

        if (distances[i] == numeric_limits<int>::max())
            cout << "INF";
        else
            cout << distances[i];

        cout << endl;
    }

    graph.printAllPaths(0, 5);

    vector<int> values = {10, 9, 2, 5, 3, 7, 101, 18};

    cout << "LIS length: "
         << longestIncreasingSubsequence(values)
         << endl;

    return 0;
}
